@router.post("/login")
def login(request: Request, payload: Credentials):
    rate_limit(request, "auth-login", limit=10, window_seconds=300, discriminator=payload.email)
    _password_policy(payload.password)
    try:
        result = _auth_client().auth.sign_in_with_password({"email": payload.email, "password": payload.password})
        session = _session_response(result)
        app_user = session.get("user") or {}
        _audit_auth(action="LOGIN_SUCCESS", request=request, actor_user_id=app_user.get("id"), target_user_id=app_user.get("id"), reason="Password authentication succeeded", after_state={"email": app_user.get("email")})
        return session
    except HTTPException:
        _audit_auth(action="LOGIN_DENIED", request=request, reason="Authentication denied", after_state={"email_domain": payload.email.rsplit("@", 1)[-1] if "@" in payload.email else None})
        raise
    except Exception:
        _audit_auth(action="LOGIN_FAILED", request=request, reason="Invalid credentials", after_state={"email_domain": payload.email.rsplit("@", 1)[-1] if "@" in payload.email else None})
        raise HTTPException(status_code=401, detail="Invalid email or password")

