@router.post("/set-password")
def set_password(request: Request, payload: SetPasswordRequest):
    _password_policy(payload.password)
    try:
        client = _auth_client()
        current = client.auth.get_user(payload.access_token)
        auth_user = current.user
        if not auth_user:
            raise ValueError("Invalid recovery token")
        attributes = {"password": payload.password}
        if payload.first_name is not None or payload.last_name is not None:
            attributes["data"] = {"first_name": payload.first_name or "", "last_name": payload.last_name or ""}
        supabase.auth.admin.update_user_by_id(str(auth_user.id), attributes)
        app_user = _application_user(str(auth_user.id))
        if not app_user:
            raise HTTPException(status_code=403, detail="User does not have admin access")
        supabase.rpc(
            "rbac_activate_invited_user",
            {
                "target_auth_user_id": str(auth_user.id),
                "event_request_id": getattr(request.state, "request_id", None),
            },
        ).execute()
        _audit_auth(action="PASSWORD_SET", request=request, actor_user_id=str(app_user["id"]), target_user_id=str(app_user["id"]), reason="Invitation or recovery password completed", after_state={"status": "active"})
        return {"message": "Password has been set successfully."}
    except HTTPException:
        raise
    except Exception as exc:
        if "invitation has expired" in str(exc).lower():
            raise HTTPException(status_code=410, detail="This invitation has expired. Request a new invitation.") from exc
        if "account is disabled" in str(exc).lower():
            raise HTTPException(status_code=403, detail="This account is disabled.") from exc
        raise HTTPException(status_code=400, detail="The reset link is invalid or has expired")

